#!/usr/bin/env python3
"""What's new in v1.4: real in-game screenshots taken on the v1.4 ROM itself (r04, 0bc34645...) in the release testing (mGBA 0.10.5 engine)
-> data/whatsnew-v1.4.json + site/assets/game/whatsnew/v1.4/.  usage: whatsnew_v14.py --workspace <VSC>"""
import argparse, hashlib, json, shutil
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
ap = argparse.ArgumentParser(); ap.add_argument("--workspace", default=str(ROOT.parent)); a = ap.parse_args(); WS = Path(a.workspace)
sha = lambda p: hashlib.sha256(Path(p).read_bytes()).hexdigest()
RC = WS / "output/project-blonde-v1.4-rc1-20261019"; man = json.loads((RC / "RELEASE-MANIFEST.json").read_text())
R04 = "0bc3464580952c6d7b41b0e7755f1d0cb35d5fceb1c388105c4fc460628f1a2a"
assert man["rom_sha256"] == R04 == sha(RC / "Pokemon - Project Blonde.gba")
EXP = "output/v1.4-exp-overworld-encounters"; R4 = "output/project-blonde-v1.4/r04-qa-corrections"
SHOTS = [("options", f"{EXP}/evidence/options-3-wild-overworld.png", "Wild Encounters",
          "A new option: START, OPTIONS, WILD ENCOUNTERS. Choose OVERWORLD to see wild Pokémon before you battle them, or keep CLASSIC."),
         ("grass", f"{EXP}/r5d/evidence/grass-r32-r04relday-6.png", "Pokémon in the grass",
          "Route 32: wild Pokémon move through the tall grass. Walk into one to battle it. The species, levels and odds are the same as CLASSIC."),
         ("underwater", f"{EXP}/r5d/evidence/uw-r04-rel-route126-start.png", "Under the sea",
          "Underwater Route 126: Clamperl and Chinchou drift along the seabed, tinted by the water around them."),
         ("primal", f"{R4}/test/evidence/r04-xspeed-slot5.png", "Primal Reversion",
          "Primal Groudon in battle. After the Silph Conspiracy, May gives you the Red Orb and Brendan the Blue Orb in Littleroot Town."),
         ("janine", f"{R4}/test/evidence/r04-A-457-SUICUNE-FIRST-page-1.png", "The Reception Gate",
          "After the Silph Conspiracy, Janine’s words at the Reception Gate follow the story.")]
out = ROOT / "site/assets/game/whatsnew/v1.4"; out.mkdir(parents=True, exist_ok=True); rows = []
from PIL import Image
for i, f, t, c in SHOTS:
    src = WS / f; dst = out / f"{i}.png"; shutil.copyfile(src, dst); assert Image.open(dst).size == (240, 160)
    rows.append({"id": i, "file": dst.name, "title": t, "caption": c, "source": f, "sha256": sha(dst)})
title = WS / "output/project-blonde-v1.4/r03-overworld-encounters/evidence/newgame-r04-title.png"; shutil.copyfile(title, ROOT / "site/assets/game/title/title-v1.4.png")
G = {"_about": "Generated by tools/whatsnew_v14.py - do not edit. Screenshots taken on the v1.4 ROM itself (r04) in its release testing, mGBA 0.10.5 engine; the grass shot with the in-game clock pinned to daytime.",
     "kind": "story", "before": {"public": "v1.3", "build": "v116", "sha256": "e851f80dfc4b0a025882bb5deeb329ce639747901a0f3e3522a21e6a6b8087c3"},
     "after": {"public": "v1.4", "build": "r04", "sha256": R04}, "screenshots_from": {"build": "r04", "sha256": R04},
     "heading": "Overworld encounters and more", "lead": "Wild Pokémon you can see before you battle them, Primal Reversion, and a story detail that now follows the Silph Conspiracy.",
     "link": ["/features/overworld-encounters/", "How overworld encounters work"], "desc": "overworld wild encounters, Primal Reversion and legendaries that stay caught",
     "title": {"file": "title-v1.4.png", "source": "output/project-blonde-v1.4/r03-overworld-encounters/evidence/newgame-r04-title.png", "sha256": sha(title)}, "shots": rows}
(ROOT / "data/whatsnew-v1.4.json").write_text(json.dumps(G, indent=1, ensure_ascii=False) + "\n"); print(len(rows), "shots")
